using UnityEngine;
using UnityEditor;
using System.IO;
using InhaExpress.Client.Presentation;
internal class CommandScript : IRunCommand {
 public void Execute(ExecutionResult result) {
 if(!EditorApplication.isPlaying)throw new System.Exception("Play mode required");
 var vehicle=Object.FindFirstObjectByType<VehicleController>();
 if(vehicle==null)throw new System.Exception("Vehicle missing");
 var body=vehicle.VehicleBody; var start=body.position; float startTime=Time.time;
 float peakVertical=0,peakSpeed=0; int samples=0,ungrounded=0;
 var wheels=vehicle.GetComponentsInChildren<WheelCollider>();
 EditorApplication.CallbackFunction sample=null;
 sample=()=>{
 if(!EditorApplication.isPlaying||vehicle==null){EditorApplication.update-=sample;return;}
 float elapsed=Time.time-startTime;
 vehicle.SetDriveCommand(elapsed<6?5:0,0,elapsed>=6);
 peakVertical=Mathf.Max(peakVertical,Mathf.Abs(body.linearVelocity.y)); peakSpeed=Mathf.Max(peakSpeed,body.linearVelocity.magnitude);
 samples++;bool grounded=false;foreach(var w in wheels)grounded|=w.isGrounded;if(!grounded)ungrounded++;
 if(elapsed>=8){
 vehicle.SetDriveCommand(0,0,true);EditorApplication.update-=sample;
 var delta=body.position-start;delta.y=0;
 File.WriteAllText("artifacts/road_smoothing/drive-smoke.txt","durationS="+elapsed+"\nhorizontalDistanceM="+delta.magnitude+"\npeakSpeedMps="+peakSpeed+"\npeakVerticalSpeedMps="+peakVertical+"\nsamples="+samples+"\nallWheelsUngroundedSamples="+ungrounded+"\nfinalSpeedMps="+body.linearVelocity.magnitude+"\n");
 Debug.Log("ROAD_DRIVE_SMOKE_COMPLETE distance="+delta.magnitude);
 }};
 EditorApplication.update+=sample;result.Log("Started temporary 5km/h straight road probe: 6s drive + 2s brake. No vehicle Transform edits.");
 }
}
